testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { montarQuerySegura } from './solution.mjs';

test('texto simples vira texto entre aspas simples', () => {
  assert.equal(
    montarQuerySegura('SELECT * FROM usuarios WHERE email = ?', ['ana@clinica.com']),
    "SELECT * FROM usuarios WHERE email = 'ana@clinica.com'",
  );
});

test("aspas do usuário são dobradas — o comando não muda de sentido", () => {
  assert.equal(
    montarQuerySegura('SELECT * FROM usuarios WHERE nome = ?', ["O'Brien"]),
    "SELECT * FROM usuarios WHERE nome = 'O''Brien'",
  );
  // a tentativa de injeção inteira vira um ÚNICO texto literal
  assert.equal(
    montarQuerySegura('SELECT * FROM usuarios WHERE nome = ?', ["' OR '1'='1"]),
    "SELECT * FROM usuarios WHERE nome = ''' OR ''1''=''1'",
  );
});

test('número fica sem aspas, booleano vira 1/0 e null vira NULL', () => {
  assert.equal(
    montarQuerySegura('SELECT * FROM consultas WHERE id = ?', [42]),
    'SELECT * FROM consultas WHERE id = 42',
  );
  assert.equal(
    montarQuerySegura('SELECT * FROM consultas WHERE confirmada = ?', [true]),
    'SELECT * FROM consultas WHERE confirmada = 1',
  );
  assert.equal(
    montarQuerySegura('SELECT * FROM consultas WHERE confirmada = ?', [false]),
    'SELECT * FROM consultas WHERE confirmada = 0',
  );
  assert.equal(
    montarQuerySegura('SELECT * FROM consultas WHERE telefone = ?', [null]),
    'SELECT * FROM consultas WHERE telefone = NULL',
  );
});

test('aplica vários valores na ordem e reclama quando a contagem não bate', () => {
  assert.equal(
    montarQuerySegura("SELECT * FROM usuarios WHERE email = ? AND senha = ?", ['a@b.com', '123']),
    "SELECT * FROM usuarios WHERE email = 'a@b.com' AND senha = '123'",
  );
  assert.throws(
    () => montarQuerySegura('SELECT * FROM usuarios WHERE email = ? AND senha = ?', ['a@b.com']),
    /marcadores/,
  );
  assert.throws(
    () => montarQuerySegura('SELECT * FROM usuarios WHERE nome = ?', [['Ana']]),
    /tipo/,
  );
});

solutionCode:
// Query parametrizada simulada: o template fica fixo e cada ? recebe um
// valor JÁ ESCAPADO — é o que o banco faz com os parâmetros de verdade.
export function montarQuerySegura(template, valores) {
  if (typeof template !== 'string') {
    throw new Error('template precisa ser texto');
  }
  if (!Array.isArray(valores)) {
    throw new Error('valores precisa ser uma lista');
  }
  // cada '?' divide o template em uma parte; N partes = N-1 marcadores
  const partes = template.split('?');
  if (partes.length - 1 !== valores.length) {
    throw new Error(
      `o template tem ${partes.length - 1} marcadores e foram passados ${valores.length} valores`,
    );
  }

  // remonta o SQL: parte + valor escapado + parte + valor escapado...
  let sql = partes[0];
  for (let i = 0; i < valores.length; i++) {
    sql = sql + escaparValor(valores[i]) + partes[i + 1];
  }
  return sql;
}

// Valor virado em SQL literal seguro: texto entre aspas (com ' dobradas),
// número sem aspas, booleano vira 1/0 e null vira NULL.
function escaparValor(valor) {
  if (typeof valor === 'number') {
    return String(valor);
  }
  if (typeof valor === 'boolean') {
    return valor ? '1' : '0';
  }
  if (valor === null) {
    return 'NULL';
  }
  if (typeof valor !== 'string') {
    throw new Error('valor precisa ser de um tipo aceito: texto, número, booleano ou null');
  }
  return `'${valor.replace(/'/g, "''")}'`;
}
